let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=status_heartbeat,status=started value=1 ' + nowNs;
return msg;

function clean(v) { return (v && v !== 'unknown' && v !== 'unavailable') ? v : null; }
const now = new Date().toISOString();
const reports = [];

// This flow's own successful execution IS the 'HA is up' signal — see
// this tab's info note for why /api/config enrichment isn't implemented.
reports.push({
    category: 'ha', component: 'ha_core',
    last_run_at: now, last_status: 'success',
    expected_frequency_minutes: 15,
    detail: 'Signal is this heartbeat itself running — real HA version/uptime not implemented yet, see flow tab info.'
});

// SQLite migration (Aug 2026) — replaces what used to be 28 chained
// api-current-state HA reads (4 fields × 7 flows) with one SELECT * FROM
// job_status, read once upstream (n_sh_query_job_status_db) and handed in
// here as msg.payload (array of row objects). last_attempt_ok is a real
// SQLite INTEGER (0/1) now, not HA's 'on'/'off' string.
const byJob = {};
(msg.payload || []).forEach(r => { byJob[r.job_name] = r; });

function pushComponent(component, jobName, expectedMin) {
    const row = byJob[jobName];
    const ok = row ? row.last_attempt_ok : null;
    const detail = (component === 'bodycomp_import' && row && row.checkpoint) ? clean(row.checkpoint) : null;
    reports.push({
        category: 'nodered',
        component: component,
        last_run_at: row ? clean(row.last_attempt) : null,
        last_status: ok === 1 ? 'success' : (ok === 0 ? 'failed' : 'unknown'),
        last_error: row ? clean(row.last_error) : null,
        expected_frequency_minutes: expectedMin,
        detail: detail,
    });
}
pushComponent('oura_sync', 'oura_sync', 240);
pushComponent('godaddy_pull', 'godaddy_pull', 15);
pushComponent('bodycomp_import', 'bodycomp_import', 1440);
// medical_history_import and wherewhen_restore are manual/on-demand only
// (no real cadence), so expectedMin is null — overdue_info() in db.php
// already treats a null expected_frequency_minutes as "not schedule-based,
// nothing to compute" rather than always-overdue. wherewhen_export has a
// real weekly schedule (Sunday 3am) alongside its manual trigger, so it
// gets a real expectedMin (7 days). analysis_engine's daily tier (~12:15pm)
// is its tightest scheduled cadence.
pushComponent('medical_history_import', 'medical_history_import', null);
pushComponent('wherewhen_export', 'wherewhen_export', 10080);
pushComponent('wherewhen_restore', 'wherewhen_restore', null);
pushComponent('analysis_engine', 'analysis_engine', 1440);
// GoDaddy Backup/Restore (Aug 2026, PLAN.md §22) -- same job_status
// rows godaddy_backup_flow.json/godaddy_restore_flow.json already write,
// just not previously in this whitelist so they never reached status.php.
// Backup is daily (3am, 1440 min); Restore is manual-only like
// wherewhen_restore/medical_history_import above.
pushComponent('godaddy_backup', 'godaddy_backup', 1440);
pushComponent('incident_digest', 'incident_digest', 1440);
pushComponent('godaddy_restore', 'godaddy_restore', null);
pushComponent('godaddy_restore_from_file', 'godaddy_restore_from_file', null); // manual only

msg.reports = reports;
return msg;

msg.url = msg.secrets.godaddy_base_url + '/api/status_push.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({ reports: msg.reports });
return msg;

const resp = msg.payload;
if (!resp || resp.success !== true) {
    msg.job_failed = true;
    msg.failure_code = resp && resp.error === 'auth_invalid' ? 'godaddy_auth_failed' : 'godaddy_error_response';
    msg.failure_detail = JSON.stringify(resp).slice(0, 300);
}

function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }
const nowNs = Date.now() * 1000000;
const lines = (msg.reports || []).map(r => {
    const ok = r.last_status === 'success' ? 1 : 0;
    return 'system_status_snapshot,category=' + esc(r.category) + ',component=' + esc(r.component) + ' status_ok=' + ok + ' ' + nowNs;
});
msg.influx_snapshot_lines = lines;
return msg;

if (!msg.influx_snapshot_lines.length) {
    return [null, msg];
}
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_snapshot_lines.join('\n');
return [msg, msg];

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
if (msg.job_failed) {
    const code = msg.failure_code || 'unknown_error';
    const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
    msg.influx_finish_point = 'sync_job_runs,job_name=status_heartbeat,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
    node.warn('Status Heartbeat failed: ' + code + ' - ' + msg.failure_detail);
} else {
    msg.influx_finish_point = 'sync_job_runs,job_name=status_heartbeat,status=success report_count=' + (msg.reports ? msg.reports.length : 0) + ',duration_ms=' + durationMs + ' ' + nowNs;
}
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;
